public partial class Cad {
    object[] NativeFeatureDiagnostics(IModelDoc2 doc) {
        var rows=new List<object>();var f=(IFeature)doc.FirstFeature();
        while(f!=null){bool warning;int error=f.GetErrorCode2(out warning);if(error!=0){IComponent2 owner=null;string ownerName=null,ownerPath=null,ownerError=null,requestedConfig=null;string[] availableConfigs=null;bool? configurationExists=null;try{owner=f.GetSpecificFeature2() as IComponent2;if(owner!=null){ownerName=owner.Name2;ownerPath=owner.GetPathName();requestedConfig=owner.ReferencedConfiguration;var part=owner.GetModelDoc2() as IModelDoc2;if(part!=null){availableConfigs=(part.GetConfigurationNames() as string[])??new string[0];configurationExists=availableConfigs.Contains(requestedConfig,StringComparer.Ordinal);}}}catch(Exception e){ownerError=e.GetType().Name;}rows.Add(new{owner_component=ownerName,referenced_part_path=ownerPath,referenced_configuration=requestedConfig,referenced_configuration_exists=configurationExists,available_configuration_count=availableConfigs==null?(int?)null:availableConfigs.Length,available_configurations=availableConfigs==null?null:availableConfigs.Take(32).ToArray(),available_configurations_truncated=availableConfigs!=null&&availableConfigs.Length>32,owner_resolution_status=owner!=null?"native_component_feature_owner_observed":"not_available_no_name_inference",owner_read_error=ownerError,referenced_path_scope="currently_resolved_path_not_original_source_path",name=f.Name,native_feature_id=f.GetID(),native_feature_type=f.GetTypeName2(),native_error=error,native_error_enum="swFeatureError_e",native_error_name=Enum.GetName(typeof(swFeatureError_e),error)??"unknown_swFeatureError_value",native_error_message=error==1?"Unknown feature error; native API did not identify the cause":"Native feature error; inspect named feature in CAD",native_hresult=(int?)null,hresult_status="not_applicable_no_COM_exception",warning=warning,causal_origin="not_proven"});}f=(IFeature)f.GetNextFeature();}
        return rows.ToArray();
    }
    object FeatureErrorGroups(object[] rows){return rows.Select(r=>Json.Deserialize<Dictionary<string,object>>(Json.Serialize(r))).GroupBy(r=>new{type=Convert.ToString(r["native_feature_type"]),code=Convert.ToInt32(r["native_error"]),warning=Convert.ToBoolean(r["warning"])}).Select(g=>new{native_feature_type=g.Key.type,native_error=g.Key.code,native_error_enum="swFeatureError_e",native_error_name=Enum.GetName(typeof(swFeatureError_e),g.Key.code),warning=g.Key.warning,count=g.Count(),feature_names=g.Take(8).Select(r=>r["name"]).ToArray(),feature_names_truncated=g.Count()>8}).ToArray();}
    void RequireResetBranchHealth(IModelDoc2 doc){bool rebuilt=doc.EditRebuild3();var rows=NativeFeatureDiagnostics(doc);if(!rebuilt||rows.Length>0)throw new CadFault("MODEL_PREFLIGHT_FAILED","新副本存在原生重建或特征错误；没有忽略错误继续归零。",new{stage="reset_branch_rebuild_preflight",native_rebuild_succeeded=rebuilt,feature_diagnostics=rows,feature_error_summary=FeatureErrorGroups(rows),causal_origin="not_proven_source_or_import_requires_separate_baseline"});}
